def num_islands(grid):
    if not grid:
        return 0
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                dfs_island(grid, i, j)
                count += 1
    return count

def dfs_island(grid, i, j):
    if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
        return
    grid[i][j] = '0'
    dfs_island(grid, i + 1, j)
    dfs_island(grid, i - 1, j)
    dfs_island(grid, i, j + 1)
    dfs_island(grid, i, j - 1)

**Generator**: Produces values with yield.

**Coroutine**: Consumes values, uses yield to receive data.

```python
# Generator (producer)
def producer():
    for i in range(5):
        yield i

# Coroutine (consumer)
def consumer():
    while True:
        value = yield  # Wait for input
        print(f"Consumed: {value}")

# Use generator
for item in producer():
    print(item)  # 0 1 2 3 4

# Use coroutine
c = consumer()
next(c)  # Prime it
c.send(1)  # Sends 1 to consumer
c.send(2)  # Sends 2 to consumer
```

**Pipeline pattern**:
```python
def producer(target):
    for i in range(5):
        target.send(i)  # Send to next

def filter_even(target):
    while True:
        value = yield
        if value % 2 == 0:
            target.send(value)

def consumer():
    while True:
        value = yield
        print(f"Final: {value}")

c = consumer()
f = filter_even(c)
producer(f)  # Pipeline: produce -> filter -> consume
```

