def min_window(s, t):
    from collections import Counter
    t_count = Counter(t)
    window = {}
    l = 0
    min_len = float('inf')
    min_l = 0
    for r in range(len(s)):
        if s[r] in t_count:
            window[s[r]] = window.get(s[r], 0) + 1
        while all(window.get(c, 0) >= t_count[c] for c in t_count):
            if r - l + 1 < min_len:
                min_len = r - l + 1
                min_l = l
            if s[l] in t_count:
                window[s[l]] -= 1
            l += 1
    return s[min_l:min_l+min_len] if min_len != float('inf') else ''

