def has_cycle(graph, n):
    def dfs(node, parent, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, node, visited):
                    return True
            elif neighbor != parent:
                return True
        return False
    visited = set()
    for i in range(n):
        if i not in visited:
            if dfs(i, -1, visited):
                return True
    return False

