import heapq

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next
    def __lt__(self, other):
        return self.val < other.val

def mergeKLists(lists):
    heap = []
    for lst in lists:
        if lst:
            heapq.heappush(heap, (lst.val, id(lst), lst))
    dummy = ListNode(0)
    current = dummy
    while heap:
        _, _, node = heapq.heappop(heap)
        current.next = node
        current = current.next
        if node.next:
