# Pattern: Two pointers (left/right) forming a window
# Expand right, contract left to maintain property

# 1. Fixed window size k
def maxSlidingWindow(nums, k):
    from collections import deque
    if not nums:
        return []
    deq = deque()
    result = []
    for i in range(len(nums)):
        while deq and deq[0][1] < i - k + 1:
            deq.popleft()
        while deq and deq[-1][0] < nums[i]:
            deq.pop()
        deq.append((nums[i], i))
        if i >= k - 1:
            result.append(deq[0][0])
    return result

print(maxSlidingWindow([1, 3, 1, 2, 0, 5], 3))  # [3, 3, 2, 5]

# 2. Variable window (contract/expand as needed)
def minWindow(s, t):
    if not s or not t:
        return ''
    t_counts = {}
    for char in t:
        t_counts[char] = t_counts.get(char, 0) + 1
    required = len(t_counts)
    left, right = 0, 0
    formed = 0
    window_counts = {}
    result = (float('inf'), 0, 0)
    while right < len(s):
        char = s[right]
        window_counts[char] = window_counts.get(char, 0) + 1
        if char in t_counts and window_counts[char] == t_counts[char]:
            formed += 1
        while left <= right and formed == required:
            if right - left + 1 < result[0]:
                result = (right - left + 1, left, right)
            char = s[left]
            window_counts[char] -= 1
            if char in t_counts and window_counts[char] < t_counts[char]:
                formed -= 1
            left += 1
        right += 1
    return '' if result[0] == float('inf') else s[result[1]:result[2] + 1]

print(minWindow('ADOBECODEBANC', 'ABC'))  # 'BANC'
```

