from collections import Counter
import heapq

def leastInterval(tasks, n):
    task_counts = Counter(tasks)
    max_heap = [-count for count in task_counts.values()]
    heapq.heapify(max_heap)
    time = 0
    while max_heap:
        interval = []
        for _ in range(n + 1):
            if max_heap:
                interval.append(heapq.heappop(max_heap))
        for count in interval:
            if count < -1:
                heapq.heappush(max_heap, count + 1)
        time += n + 1 if max_heap else len(interval)
    return time

print(leastInterval(['A', 'A', 'A', 'B', 'B', 'B'], 2))  # 8
