def serialize(root):
    def dfs(node):
        if not node:
            return ['#']
        return [str(node.val)] + dfs(node.left) + dfs(node.right)
    return ' '.join(dfs(root))

def deserialize(data):
    def dfs(nodes):
        val = nodes.pop(0)
        if val == '#':
            return None
        node = TreeNode(int(val))
        node.left = dfs(nodes)
        node.right = dfs(nodes)
        return node
    return dfs(data.split())

def decode(s):
    if not s or s[0] == '0':
        return 0
    dp = [0] * (len(s) + 1)
    dp[0] = dp[1] = 1
    for i in range(2, len(s) + 1):
        if s[i-1] != '0':
            dp[i] += dp[i-1]
        if 10 <= int(s[i-2:i]) <= 26:
            dp[i] += dp[i-2]
    return dp[len(s)]

class CircularQueue:
    def __init__(self, size):
        self.queue = [None] * size
        self.front = -1
        self.rear = -1
    def enqueue(self, data):
        if self.rear == (self.front - 1) % len(self.queue):
            return
        if self.front == -1:
            self.front = 0
        self.rear = (self.rear + 1) % len(self.queue)
        self.queue[self.rear] = data

