from collections import deque
def right_view(root):
    if not root:
        return []
    result = []
    q = deque([(root, 0)])
    while q:
        node, level = q.popleft()
        if level == len(result):
            result.append(node.val)
        if node.left:
            q.append((node.left, level + 1))
        if node.right:
            q.append((node.right, level + 1))
    return result

