from collections import deque

def maxSlidingWindow(nums, k):
    if not nums:
        return []
    deq = deque()
    result = []
    for i in range(len(nums)):
        while deq and deq[0][1] < i - k + 1:
            deq.popleft()
        while deq and deq[-1][0] < nums[i]:
            deq.pop()
        deq.append((nums[i], i))
        if i >= k - 1:
            result.append(deq[0][0])
    return result

