def has_cycle_directed(graph):
    def dfs(node, state):
        if state[node] == 1:
            return True
        if state[node] == 2:
            return False
        state[node] = 1
        for neighbor in graph[node]:
            if dfs(neighbor, state):
                return True
        state[node] = 2
        return False
    state = {node: 0 for node in graph}
    for node in graph:
        if state[node] == 0:
            if dfs(node, state):
                return True
    return False

