import bisect

def lengthOfLIS(nums):
    if not nums:
        return 0
    # tails[i] = smallest ending value of increasing subsequence of length i+1
    tails = []
    for num in nums:
        pos = bisect.bisect_left(tails, num)
        if pos == len(tails):
            tails.append(num)
        else:
            tails[pos] = num
    return len(tails)

print(lengthOfLIS([10, 9, 2, 5, 3, 7, 101, 18]))  # 4
print(lengthOfLIS([0, 1, 0, 4, 4, 4, 3, 5, 5]))  # 5

# Time: O(n log n) via binary search
# Space: O(n) for tails array
# Note: tails array doesn't represent actual LIS, just length tracking
