def longestMountain(arr):
    if len(arr) < 3:
        return 0
    max_length = 0
    i = 1
    while i < len(arr) - 1:
        if arr[i - 1] < arr[i] > arr[i + 1]:
            left = i - 1
            while left > 0 and arr[left - 1] < arr[left]:
                left -= 1
            right = i + 1
            while right < len(arr) - 1 and arr[right] > arr[right + 1]:
                right += 1
            max_length = max(max_length, right - left + 1)
        i += 1
    return max_length

print(longestMountain([2, 1, 4, 7, 3, 2, 5]))  # 5
print(longestMountain([2, 2, 2]))  # 0
```

Auto-currying automatically converts a multi-argument function into a chain of single-argument functions.

```python
def auto_curry(func):
    from functools import wraps
    @wraps(func)
    def curried(*args):
        if len(args) >= func.__code__.co_argcount:
            return func(*args)
        return lambda *more_args: curried(*(args + more_args))
    return curried

@auto_curry
def add(a, b, c):
    return a + b + c

print(add(1)(2)(3))      # 6
print(add(1, 2)(3))      # 6
print(add(1)(2, 3))      # 6
print(add(1, 2, 3))      # 6
```

