def hasCycle(numCourses, prerequisites):
    graph = [[] for _ in range(numCourses)]
    for u, v in prerequisites:
        graph[u].append(v)
    colors = [0] * numCourses
    def dfs(node):
        if colors[node] == 1:
            return True
        if colors[node] == 2:
            return False
        colors[node] = 1
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        colors[node] = 2
        return False
    for i in range(numCourses):
        if colors[i] == 0 and dfs(i):
            return True
    return False

