def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def twin_primes(limit):
    result = []
    for i in range(2, limit - 2):
        if is_prime(i) and is_prime(i + 2):
            result.append((i, i + 2))
    return result

