def prim(graph, start, n):
    visited = [False] * n
    min_edge = [float('inf')] * n
    mst = []
    visited[start] = True
    for neighbor, weight in graph[start]:
        min_edge[neighbor] = weight
    for _ in range(n - 1):
        u = min(i for i in range(n) if not visited[i] and min_edge[i] != float('inf'))
        visited[u] = True
        for neighbor, weight in graph[u]:
            if not visited[neighbor] and weight < min_edge[neighbor]:
                min_edge[neighbor] = weight
    return mst

def two_sum(arr, target):
    l, r = 0, len(arr) - 1
    while l < r:
        s = arr[l] + arr[r]
        if s == target:
            return [l, r]
        elif s < target:
            l += 1
        else:
            r -= 1

